import{G as e,W as t,n,rt as r}from"./chunks/framework.CJ3GlOSn.js";import{S as i}from"./chunks/assets.DMkeNHu3.js";var a=JSON.parse(`{"title":"Post Management Documentation (Post)","description":"","frontmatter":{},"headers":[],"relativePath":"02-consumer/09-post.md","filePath":"02-consumer/09-post.md"}`),o={name:`02-consumer/09-post.md`};function s(n,a,o,s,c,l){return r(),t(`div`,null,[...a[0]||=[e(`<h1 id="post-management-documentation-post" tabindex="-1">Post Management Documentation (Post) <a class="header-anchor" href="#post-management-documentation-post" aria-label="Permalink to “Post Management Documentation (Post)”">​</a></h1><p><img src="`+i+`" alt="post.webp" width="1920" height="2056"></p><h2 id="_1-introduction" tabindex="-1">1. Introduction <a class="header-anchor" href="#_1-introduction" aria-label="Permalink to “1. Introduction”">​</a></h2><p>The post management panel is used to create, edit, organize, and publish the site&#39;s textual content. It provides the administrator with features such as editing post content, managing the featured image, categories, tags, attachments, SEO settings, custom themes, and Schema Markup.</p><p>The post editing form consists of a main section for post information and content, and a sidebar for additional settings. The lower section of the form contains settings for the main group, featured image, publication status, and pinning the post.</p><p>The <code>Post</code> model is the core of this section. It manages post information, relationships with the author and groups, publication status, SEO settings, and features related to public display.</p><h2 id="_2-main-post-information" tabindex="-1">2. Main Post Information <a class="header-anchor" href="#_2-main-post-information" aria-label="Permalink to “2. Main Post Information”">​</a></h2><h3 id="title" tabindex="-1">Title <a class="header-anchor" href="#title" aria-label="Permalink to “Title”">​</a></h3><p>The post&#39;s main title is used to introduce the content and display it in different sections of the site.</p><p>This value is stored in the <code>title</code> field of the <code>Post</code> model and can be translated.</p><h3 id="slug" tabindex="-1">Slug <a class="header-anchor" href="#slug" aria-label="Permalink to “Slug”">​</a></h3><p>The slug is the post&#39;s text identifier in the URL. It must be unique for each post and is used to route to the public post page.</p><p>The <code>Post</code> model overrides the <code>getRouteKeyName()</code> method to select the <code>slug</code> field as the routing key. Therefore, posts are identified by their slug through Route Model Binding.</p><p>When creating or editing a post, it is best to keep the slug short, readable, and relevant to the content title.</p><h3 id="subtitle" tabindex="-1">Subtitle <a class="header-anchor" href="#subtitle" aria-label="Permalink to “Subtitle”">​</a></h3><p>The subtitle provides a brief description of the post&#39;s subject and can be displayed alongside the main title or in the content introduction section.</p><p>This value is stored in the <code>subtitle</code> field and can be translated.</p><h3 id="post-text" tabindex="-1">Post Text <a class="header-anchor" href="#post-text" aria-label="Permalink to “Post Text”">​</a></h3><p>The post&#39;s main content is managed through the rich-text editor. The editor supports writing and formatting text, creating headings, and organizing post content.</p><p>The content in this section is stored in the <code>body</code> field of the <code>Post</code> model and can be translated.</p><p>The structure of HTML headings in post content is particularly important because the automatic table of contents uses the headings in the text to generate the list.</p><h2 id="_3-content-editor-and-seo-analysis" tabindex="-1">3. Content Editor and SEO Analysis <a class="header-anchor" href="#_3-content-editor-and-seo-analysis" aria-label="Permalink to “3. Content Editor and SEO Analysis”">​</a></h2><p>One of the key features of the post editing form is the SEO analysis tool alongside the content editor. This tool checks the status of the post content and provides suggestions for improving writing quality and optimization.</p><h3 id="keyword" tabindex="-1">Keyword <a class="header-anchor" href="#keyword" aria-label="Permalink to “Keyword”">​</a></h3><p>In this section, the post&#39;s primary keyword is specified. The content analysis tool uses this value to check keyword usage and provide relevant suggestions.</p><p>This value is stored in the <code>keyword</code> field of the <code>Post</code> model.</p><h3 id="seo-score" tabindex="-1">SEO Score <a class="header-anchor" href="#seo-score" aria-label="Permalink to “SEO Score”">​</a></h3><p>The SEO score shows the overall status of the content analysis. It is calculated based on the criteria implemented in the project&#39;s content analysis tool.</p><h3 id="optimization-recommendations" tabindex="-1">Optimization Recommendations <a class="header-anchor" href="#optimization-recommendations" aria-label="Permalink to “Optimization Recommendations”">​</a></h3><p>The Recommendations section provides suggestions for improving the content. These may include:</p><ul><li>Increasing the content length if the text is too short</li><li>Adjusting keyword usage</li><li>Using the keyword in headings</li><li>Shortening long and complex sentences</li><li>Dividing the text into suitable paragraphs</li><li>Adding headings to create a more organized structure</li><li>Using lists to improve readability</li></ul><p>Metrics such as content length, keyword repetition, average sentence length, and paragraph structure are also displayed.</p><p>The purpose of this section is to help the author identify potential content issues and improve its structure before publication. The SEO score alone does not guarantee a better ranking in search engine results.</p><h2 id="_4-featured-image-index-image" tabindex="-1">4. Featured Image (Index Image) <a class="header-anchor" href="#_4-featured-image-index-image" aria-label="Permalink to “4. Featured Image (Index Image)”">​</a></h2><p>The post&#39;s featured image is selected from the panel&#39;s sidebar. It can be used on the public post page, in article lists, and in other content display sections.</p><p>The <code>Post</code> model uses the Media Library and the <code>post-image</code> image conversion to provide a processed version of the image.</p><p>When the image conversion is registered, its dimensions are obtained from the <code>post_thumb</code> setting and the <code>imageSizeConvertValidate()</code> function. The image is cropped, optimized, and sharpened, and the site logo is applied to it if the watermark setting is enabled.</p><p>The <code>imgUrl()</code> method returns the URL of the post&#39;s first converted media item. If no media image exists, the site&#39;s default logo is used instead.</p><p>The <code>orgUrl()</code> method is used to retrieve the URL of the post&#39;s first original media item.</p><h2 id="_5-post-groups-and-organization" tabindex="-1">5. Post Groups and Organization <a class="header-anchor" href="#_5-post-groups-and-organization" aria-label="Permalink to “5. Post Groups and Organization”">​</a></h2><h3 id="main-group" tabindex="-1">Main Group <a class="header-anchor" href="#main-group" aria-label="Permalink to “Main Group”">​</a></h3><p>The post&#39;s main group is specified through the <code>group_id</code> field, and the <code>mainGroup()</code> relationship retrieves it from the <code>Group</code> model.</p><p>Each post must be associated with a main group. This relationship is used to organize content and apply the site&#39;s grouping structure.</p><h3 id="groups" tabindex="-1">Groups <a class="header-anchor" href="#groups" aria-label="Permalink to “Groups”">​</a></h3><p>The <code>groups()</code> relationship establishes a many-to-many relationship with the <code>Group</code> model and allows a post to be associated with other groups.</p><p>The main group and related groups are not the same concept: the main group is obtained from the <code>group_id</code> field, while related groups are obtained through the many-to-many relationship.</p><h3 id="tags" tabindex="-1">Tags <a class="header-anchor" href="#tags" aria-label="Permalink to “Tags”">​</a></h3><p>The Tags section is intended for adding tags related to the post&#39;s subject. Tags help organize and categorize content by topic.</p><p>The information provided for the <code>Post</code> model does not specify a separate tag model or relationship; therefore, the way tags are stored and associated should be checked in the relevant tag implementation.</p><h2 id="_6-automatic-table-of-contents" tabindex="-1">6. Automatic Table of Contents <a class="header-anchor" href="#_6-automatic-table-of-contents" aria-label="Permalink to “6. Automatic Table of Contents”">​</a></h2><p>The automatic table of contents is one of the key features of the post panel. It allows a list of headings in the post content to be generated.</p><p>This feature is controlled by the <code>Table of contents</code> option next to the Slug field, and its state is stored in the <code>table_of_contents</code> field of the <code>Post</code> model.</p><h3 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to “How It Works”">​</a></h3><p>When this option is enabled, the table of contents is generated from HTML headings ranging from <code>h1</code> to <code>h6</code>.</p><p>To use this feature correctly, structure the post content with semantic headings. Using appropriate headings helps generate the table of contents and improves content readability.</p><h3 id="implementation-notes" tabindex="-1">Implementation Notes <a class="header-anchor" href="#implementation-notes" aria-label="Permalink to “Implementation Notes”">​</a></h3><ul><li>Use appropriate headings for the post&#39;s main sections.</li><li>Structure subheadings hierarchically.</li><li>Enabling a table of contents may not be necessary for short posts.</li><li>After publication, check how the table of contents appears on the public page.</li></ul><p>Enabling this option specifies whether a table of contents should be generated; its placement and final appearance depend on the theme implementation and the post display section.</p><h2 id="_7-post-icon-icon" tabindex="-1">7. Post Icon (Icon) <a class="header-anchor" href="#_7-post-icon-icon" aria-label="Permalink to “7. Post Icon (Icon)”">​</a></h2><p>The Icon section allows you to select a custom icon for the post. The selected icon is stored in the <code>icon</code> field.</p><p>This field stores the name of the selected icon from the Remix Icon collection. Using an icon depends on whether the theme and site sections support displaying it.</p><h2 id="_8-attachments" tabindex="-1">8. Attachments <a class="header-anchor" href="#_8-attachments" aria-label="Permalink to “8. Attachments”">​</a></h2><p>The Attachments section is used to manage files related to the post. Required attachments can be added to the post from this section.</p><p>The <code>Post</code> model establishes a polymorphic <code>morphMany</code> relationship with the <code>Attachment</code> model through the <code>attachs()</code> method.</p><p>This relationship allows files to be attached to the post, and its polymorphic structure allows other models to use the same attachment mechanism.</p><p>After adding a file, check its accessibility and display on the public post page.</p><h2 id="_9-canonical-url" tabindex="-1">9. Canonical URL <a class="header-anchor" href="#_9-canonical-url" aria-label="Permalink to “9. Canonical URL”">​</a></h2><p>The Canonical field specifies the post&#39;s reference URL in the SEO settings. Its value is stored in the <code>canonical</code> field of the <code>Post</code> model.</p><p>When content is accessible through multiple URLs, specifying a reference URL can help search engines identify the original version of the content.</p><p>This field is optional and should be filled in with the valid URL of the original post when necessary.</p><h2 id="_10-custom-post-theme-theme" tabindex="-1">10. Custom Post Theme (Theme) <a class="header-anchor" href="#_10-custom-post-theme-theme" aria-label="Permalink to “10. Custom Post Theme (Theme)”">​</a></h2><p>The <code>Post</code> model has a <code>theme</code> field that stores custom post theme information as JSON.</p><p>This feature allows custom display settings to be defined for a post without requiring every part of its display to follow the site&#39;s general theme.</p><p>A non-<code>NULL</code> value in this field must be valid JSON.</p><p>The architecture of custom themes and how their components are loaded are described in the documentation for the <code>Part</code> model.</p><h2 id="_11-pinning-a-post-pin" tabindex="-1">11. Pinning a Post (Pin) <a class="header-anchor" href="#_11-pinning-a-post-pin" aria-label="Permalink to “11. Pinning a Post (Pin)”">​</a></h2><p>The Pin feature is used to mark important posts. This option is located in the lower section of the form and is labeled Pin.</p><p>The post&#39;s pinned status is stored in the <code>is_pinned</code> field of the <code>Post</code> model.</p><h3 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to “Usage”">​</a></h3><p>Enabling Pin marks the post as pinned. This feature can be used to highlight announcements, important content, or posts that need more attention.</p><p>Disabling it removes the post&#39;s pinned status.</p><h3 id="implementation-notes-1" tabindex="-1">Implementation Notes <a class="header-anchor" href="#implementation-notes-1" aria-label="Permalink to “Implementation Notes”">​</a></h3><ul><li>Use this feature for important content and essential announcements.</li><li>Set the Pin status according to the post&#39;s importance and content needs.</li><li>After saving, check how the pinned post appears in the public section of the site.</li></ul><p>An enabled <code>is_pinned</code> value records the pinned status; the display order and placement of pinned posts depend on the site&#39;s public display logic.</p><h2 id="_12-publication-status" tabindex="-1">12. Publication Status <a class="header-anchor" href="#_12-publication-status" aria-label="Permalink to “12. Publication Status”">​</a></h2><p>The Status field specifies the post&#39;s publication status, and its value is stored in the <code>status</code> field.</p><p>The defined values are:</p><ul><li><code>0</code>: Draft</li><li><code>1</code>: Published</li></ul><p>The draft status is used to keep content that is not yet ready for publication. The published status is used for posts that should be available to users.</p><p>Before publication, it is best to check the post&#39;s title, Slug, content, featured image, and required settings.</p><h2 id="_13-schema-markup" tabindex="-1">13. Schema Markup <a class="header-anchor" href="#_13-schema-markup" aria-label="Permalink to “13. Schema Markup”">​</a></h2><p>The Markups section at the bottom of the page is intended for managing custom structured data for the post.</p><p>This section&#39;s information is stored in the <code>markups</code> field of the <code>Post</code> model. The <code>markup()</code> method is also provided to generate Schema Markup for the post.</p><p>The <code>markupKeywords()</code> method provides a list of variables that can be used to create Schema Markup. Based on the available information, the application name from <code>app.name</code> and the post title from <code>title</code> are among these variables.</p><p>The generated Schema type and the details of the final output depend on the implementation of the <code>markup()</code> method.</p><p>When using structured data, it is best to check that the information is accurate and consistent with the post&#39;s actual content.</p><h2 id="_14-saving-and-publishing-a-post" tabindex="-1">14. Saving and Publishing a Post <a class="header-anchor" href="#_14-saving-and-publishing-a-post" aria-label="Permalink to “14. Saving and Publishing a Post”">​</a></h2><p>After completing the information, the Save button is available to save changes.</p><p>When creating or editing a post, the main information, content, relationships, and additional settings must be recorded correctly. The publication status determines whether the post remains a draft or is published.</p><p>The <code>Post</code> model also stores information such as the view count (<code>view</code>), likes (<code>like</code>), dislikes (<code>dislike</code>), and short identifier (<code>hash</code>). These are model fields and are not necessarily editable form inputs.</p><h2 id="_15-pre-publication-checklist" tabindex="-1">15. Pre-Publication Checklist <a class="header-anchor" href="#_15-pre-publication-checklist" aria-label="Permalink to “15. Pre-Publication Checklist”">​</a></h2><p>Check the following items before publishing each post.</p><h3 id="information-and-content" tabindex="-1">Information and Content <a class="header-anchor" href="#information-and-content" aria-label="Permalink to “Information and Content”">​</a></h3><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-0" disabled="disabled"><label class="task-list-item-label" for="task-item-0"> The post title has been entered and is readable.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-1" disabled="disabled"><label class="task-list-item-label" for="task-item-1"> The Slug is appropriate and unique.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-2" disabled="disabled"><label class="task-list-item-label" for="task-item-2"> The subtitle and main content are complete.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-3" disabled="disabled"><label class="task-list-item-label" for="task-item-3"> The heading and paragraph structure has been checked.</label></li></ul><h3 id="seo-and-content-structure" tabindex="-1">SEO and Content Structure <a class="header-anchor" href="#seo-and-content-structure" aria-label="Permalink to “SEO and Content Structure”">​</a></h3><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-4" disabled="disabled"><label class="task-list-item-label" for="task-item-4"> The primary keyword has been specified.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-5" disabled="disabled"><label class="task-list-item-label" for="task-item-5"> The SEO analysis recommendations have been reviewed.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-6" disabled="disabled"><label class="task-list-item-label" for="task-item-6"> The Canonical URL has been set if necessary.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-7" disabled="disabled"><label class="task-list-item-label" for="task-item-7"> Schema Markup has been reviewed if necessary.</label></li></ul><h3 id="media-and-organization" tabindex="-1">Media and Organization <a class="header-anchor" href="#media-and-organization" aria-label="Permalink to “Media and Organization”">​</a></h3><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-8" disabled="disabled"><label class="task-list-item-label" for="task-item-8"> The featured image has been selected.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-9" disabled="disabled"><label class="task-list-item-label" for="task-item-9"> The post&#39;s main group has been set correctly.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-10" disabled="disabled"><label class="task-list-item-label" for="task-item-10"> Related groups and tags have been added if necessary.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-11" disabled="disabled"><label class="task-list-item-label" for="task-item-11"> A custom icon has been selected if necessary.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-12" disabled="disabled"><label class="task-list-item-label" for="task-item-12"> Required attachments have been added.</label></li></ul><h3 id="custom-features" tabindex="-1">Custom Features <a class="header-anchor" href="#custom-features" aria-label="Permalink to “Custom Features”">​</a></h3><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-13" disabled="disabled"><label class="task-list-item-label" for="task-item-13"> The automatic table of contents has been enabled if necessary.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-14" disabled="disabled"><label class="task-list-item-label" for="task-item-14"> The Pin status has been set according to the post&#39;s importance.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-15" disabled="disabled"><label class="task-list-item-label" for="task-item-15"> The custom post theme has been configured if necessary.</label></li></ul><h3 id="saving-and-final-review" tabindex="-1">Saving and Final Review <a class="header-anchor" href="#saving-and-final-review" aria-label="Permalink to “Saving and Final Review”">​</a></h3><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-16" disabled="disabled"><label class="task-list-item-label" for="task-item-16"> The publication status has been selected correctly.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-17" disabled="disabled"><label class="task-list-item-label" for="task-item-17"> The post preview has been checked for content and display.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-18" disabled="disabled"><label class="task-list-item-label" for="task-item-18"> The changes have been saved.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-19" disabled="disabled"><label class="task-list-item-label" for="task-item-19"> After publication, the public post page and the table of contents, featured image, and Pin status have been checked.</label></li></ul><p><strong>Final note:</strong> The table of contents and Pin options record the post&#39;s intended status in the model; however, their actual display and behavior depend on the theme implementation and the public site. Therefore, checking the result on the public page is part of completing and publishing a post.</p>`,113)]])}var c=n(o,[[`render`,s]]);export{a as __pageData,c as default};